impl Default for BridgeConfig {
    fn default() -> Self {
        BridgeConfig { ring_target_ms: 0.0, loopback_enabled: true }
    }
}

impl BridgeConfig {
    /// Clamps `ring_target_ms` into 0..=200 ms (NaN -> 0); `loopback_enabled` is a flag.
